<script setup lang="ts">
import {computed,ref} from 'vue';import {useRestaurant} from '../store';import {money,amountToCents} from '../domain';
const s=useRestaurant(),category=ref('Todos'),search=ref(''),creating=ref(false),name=ref(''),price=ref(''),newCategory=ref('Platos fuertes');
const dishes=computed(()=>s.state.dishes.filter(d=>(category.value==='Todos'||d.category===category.value)&&d.name.toLowerCase().includes(search.value.toLowerCase())));
function create(){s.act(()=>{if(s.role!=='Admin')throw Error('Solo administrador.');const cents=amountToCents(price.value);if(!name.value.trim())throw Error('Ingresá un nombre.');s.state.dishes.push({id:Math.max(...s.state.dishes.map(d=>d.id))+1,name:name.value.trim(),price:cents,category:newCategory.value,available:true,icon:'🍽'});s.save('Platillo agregado.');creating.value=false;name.value='';price.value='';});}
</script><template><div class="page-heading"><div><p class="eyebrow">SABORES DE LA CASA</p><h1>Nuestro catálogo</h1><p class="muted">Lo que servimos, preparado con cuidado.</p></div><button v-if="s.role==='Admin'" class="primary" @click="creating=!creating">＋ Agregar platillo</button></div><form v-if="creating" class="panel menu-form" @submit.prevent="create"><h2>Nuevo platillo</h2><label>Nombre<input v-model="name" maxlength="120" required/></label><label>Precio final (Q)<input v-model="price" inputmode="decimal" required/></label><label>Categoría<select v-model="newCategory"><option>Platos fuertes</option><option>Entradas</option><option>Bebidas</option><option>Postres</option></select></label><button class="primary">Guardar platillo</button></form><div class="catalog-toolbar"><div class="tabs"><button v-for="c in ['Todos','Entradas','Platos fuertes','Bebidas','Postres']" :class="{active:category===c}" @click="category=c">{{c}}</button></div><input v-model="search" placeholder="Buscar en el catálogo…" aria-label="Buscar en el catálogo"/></div><div class="menu-grid"><article v-for="d in dishes" :key="d.id" class="menu-card" :class="{unavailable:!d.available}"><div class="dish-art">{{d.icon}}</div><div class="menu-card-content"><p class="eyebrow">{{d.category}}</p><h2>{{d.name}}</h2><div class="inline"><strong class="price">{{money(d.price)}}</strong><button v-if="s.role==='Admin'" class="availability" @click="d.available=!d.available;s.save('Disponibilidad actualizada')">{{d.available?'● Disponible':'○ No disponible'}}</button><span v-else>{{d.available?'Disponible':'No disponible'}}</span></div></div></article></div><p v-if="!dishes.length" class="empty">No encontramos platillos con esa búsqueda.</p></template>